// 3D model of the nasal cavity and paranasal sinuses (right side; septum and
// frontal and sphenoid sinuses midline) from Z-Anatomy meshes (CC BY-SA 4.0,
// based on BodyParts3D): the bones and cartilages of the nose, the conchae,
// the frontal and sphenoid sinuses and ethmoid cells, the nasal lining and the
// neighbouring orbit, optic nerve, carotid and pituitary. The maxillary sinus
// (Z-Anatomy's maxilla is solid) and the drainage routes of the sinuses are
// built for this app. Geometry and the traced routes live in
// data/sinonasal-meshes.js, generated by tools/export_zanatomy.py.
// Coordinates are centimetres: +y = superior, +z = anterior, right side -x.

window.ANATOMY = window.ANATOMY || { regions: {} };
window.ANATOMY.models = window.ANATOMY.models || {};

window.ANATOMY.models.sinonasal = {
  // Default view: from the front and to the right.
  camera: { target: [0, 0.2, 0], radius: 24, theta: -0.7, phi: 1.5 },

  // [theta, phi] for the view buttons. "Medial" looks from the left with the
  // septum in front; turn bone off to see the lateral wall.
  views: {
    lateral: [-Math.PI / 2, Math.PI / 2],
    inferior: [Math.PI / 2, Math.PI / 2],
    anterior: [0, Math.PI / 2],
    // A 0° endoscope in the right nostril, looking back along the floor of the
    // nose: inferior and middle turbinates on the lateral wall, septum medially.
    special: {
      at: [0.02, 1.768, 5.1, [0.75, -0.6, -1.5]],
      layers: ["mucosa", "foramina"],
      opacity: { nasal_mucosa: 1, nasopharynx: 1 }
    }
  },
  viewLabels: { inferior: "Medial", anterior: "Front", special: "Endoscope" },

  // Starting axial level (0 = bottom, 1 = top): through the maxillary sinus and middle meatus.
  sectionLevel: 0.27,

  look: {
    frontal: { kind: "bone", opacity: 0.4 },
    ethmoid: { kind: "bone", color: 0xe3d2ae, opacity: 0.7 },
    inferior_concha: { kind: "bone", color: 0xe3d2ae },
    maxilla: { kind: "bone", opacity: 0.35 },
    sphenoid: { kind: "bone", color: 0xe6d6b4, opacity: 0.45 },
    vomer: { kind: "bone", opacity: 0.6 },
    nasal_bones: { kind: "bone" },
    palatine: { kind: "bone", opacity: 0.6 },
    septal_cartilage: { kind: "cartilage", color: 0xc9d6e0, opacity: 0.8 },
    upper_lateral: { kind: "cartilage", color: 0xc9d6e0 },
    alar: { kind: "cartilage", color: 0xc9d6e0 },
    frontal_sinus: { kind: "space", color: 0x5fb3ff, opacity: 0.55 },
    sphenoid_sinus: { kind: "space", color: 0x9b7be0, opacity: 0.55 },
    anterior_ethmoid: { kind: "space", color: 0x6fcf97, opacity: 0.6 },
    middle_ethmoid: { kind: "space", color: 0x4fd1c5, opacity: 0.6 },
    posterior_ethmoid: { kind: "space", color: 0x7fe0a0, opacity: 0.6 },
    maxillary_sinus: { kind: "space", color: 0xf2c14e, opacity: 0.45 },
    nasal_mucosa: { kind: "mucosa", color: 0xe0a4a0, opacity: 0.25 },
    nasopharynx: { kind: "gland", color: 0xd48a86, opacity: 0.35 },
    nasolacrimal: { kind: "duct", color: 0x8fc7d8 },
    orbit_contents: { kind: "cartilage", color: 0xf2efe8, opacity: 0.5 },
    pituitary: { kind: "gland", color: 0xd9906e },
    cn1: { kind: "nerve" },
    cn2: { kind: "nerve", color: 0xf0d27a },
    v2: { kind: "nerve", color: 0xf2c94c },
    ethmoidal_arteries: { kind: "artery" },
    sphenopalatine: { kind: "artery" },
    greater_palatine: { kind: "artery" },
    ica: { kind: "artery" },
    frontal_drainage: { kind: "duct", color: 0x2fb7a0 },
    maxillary_drainage: { kind: "duct", color: 0x2fb7a0 },
    sphenoid_drainage: { kind: "duct", color: 0x2fb7a0 }
  },

  build(THREE, h) {
    return h.fromMeshes("sinonasal", this.look);
  }
};
